-- GuideMe V5 experimental schema. Never run against an active GuideMe.db.
PRAGMA foreign_keys=ON;
CREATE TABLE Guides(GuideId INTEGER PRIMARY KEY,GuideKey TEXT NOT NULL UNIQUE,GuideName TEXT NOT NULL);
CREATE TABLE GuideApplicationContexts(GuideId INTEGER NOT NULL,ContextId TEXT NOT NULL,Runtime TEXT NOT NULL,PRIMARY KEY(GuideId,ContextId),FOREIGN KEY(GuideId) REFERENCES Guides(GuideId));
CREATE TABLE ApplicationContextMatchers(GuideId INTEGER NOT NULL,ContextId TEXT NOT NULL,MatcherId TEXT NOT NULL,MatcherOrder INTEGER NOT NULL,Kind TEXT NOT NULL,Value TEXT NOT NULL,PRIMARY KEY(GuideId,ContextId,MatcherId),UNIQUE(GuideId,ContextId,MatcherOrder),FOREIGN KEY(GuideId,ContextId) REFERENCES GuideApplicationContexts(GuideId,ContextId));
CREATE TABLE GuideSteps(GuideId INTEGER NOT NULL,StepId TEXT NOT NULL,StepOrder INTEGER NOT NULL,IsEnabled INTEGER NOT NULL CHECK(IsEnabled IN(0,1)),ApplicationContextId TEXT,Runtime TEXT,AutoFocusTarget INTEGER NOT NULL CHECK(AutoFocusTarget IN(0,1)),ContextKind TEXT,ContextValue TEXT,PRIMARY KEY(GuideId,StepId),UNIQUE(GuideId,StepOrder),FOREIGN KEY(GuideId) REFERENCES Guides(GuideId),FOREIGN KEY(GuideId,ApplicationContextId) REFERENCES GuideApplicationContexts(GuideId,ContextId));
CREATE TABLE StepBubbles(GuideId INTEGER NOT NULL,StepId TEXT NOT NULL,Content TEXT NOT NULL,Placement TEXT NOT NULL,PRIMARY KEY(GuideId,StepId),FOREIGN KEY(GuideId,StepId) REFERENCES GuideSteps(GuideId,StepId));
CREATE TABLE StepInteractions(GuideId INTEGER NOT NULL,StepId TEXT NOT NULL,InteractionKind TEXT NOT NULL,ElementUsageId TEXT,Explanation TEXT NOT NULL,IsAuthorConfirmed INTEGER NOT NULL CHECK(IsAuthorConfirmed IN(0,1)),PRIMARY KEY(GuideId,StepId),FOREIGN KEY(GuideId,StepId) REFERENCES GuideSteps(GuideId,StepId),FOREIGN KEY(GuideId,StepId,ElementUsageId) REFERENCES StepElementUsages(GuideId,StepId,UsageId));
CREATE TABLE GuideElements(GuideId INTEGER NOT NULL,ElementId TEXT NOT NULL,SourceStepId TEXT,Runtime TEXT,FrameContextJson TEXT,DisplayName TEXT NOT NULL,DefinitionStatus TEXT NOT NULL,PRIMARY KEY(GuideId,ElementId),FOREIGN KEY(GuideId) REFERENCES Guides(GuideId));
CREATE TABLE ElementLocators(GuideId INTEGER NOT NULL,ElementId TEXT NOT NULL,LocatorId TEXT NOT NULL,Strategy TEXT NOT NULL,Value TEXT NOT NULL,PRIMARY KEY(GuideId,ElementId,LocatorId),FOREIGN KEY(GuideId,ElementId) REFERENCES GuideElements(GuideId,ElementId));
CREATE TABLE ElementAnchorRelations(GuideId INTEGER NOT NULL,ElementId TEXT NOT NULL,AnchorElementId TEXT NOT NULL,Relation TEXT NOT NULL,AnchorOrder INTEGER NOT NULL,RelationId TEXT NOT NULL,PRIMARY KEY(GuideId,ElementId,RelationId),UNIQUE(GuideId,ElementId,AnchorOrder),FOREIGN KEY(GuideId,ElementId) REFERENCES GuideElements(GuideId,ElementId),FOREIGN KEY(GuideId,AnchorElementId) REFERENCES GuideElements(GuideId,ElementId));
CREATE TABLE StepElementUsages(GuideId INTEGER NOT NULL,StepId TEXT NOT NULL,UsageId TEXT NOT NULL,ElementId TEXT NOT NULL,Purpose TEXT NOT NULL,PRIMARY KEY(GuideId,StepId,UsageId),FOREIGN KEY(GuideId,StepId) REFERENCES GuideSteps(GuideId,StepId),FOREIGN KEY(GuideId,ElementId) REFERENCES GuideElements(GuideId,ElementId));
CREATE TABLE GuideVariables(GuideId INTEGER NOT NULL,VariableId TEXT NOT NULL,DisplayName TEXT NOT NULL,DataType TEXT NOT NULL,PRIMARY KEY(GuideId,VariableId),FOREIGN KEY(GuideId) REFERENCES Guides(GuideId));
CREATE TABLE StepCaptures(GuideId INTEGER NOT NULL,StepId TEXT NOT NULL,CaptureId TEXT NOT NULL,VariableId TEXT NOT NULL,TargetUsageId TEXT NOT NULL,Property TEXT NOT NULL,Pattern TEXT,Timing TEXT,PRIMARY KEY(GuideId,StepId,CaptureId),FOREIGN KEY(GuideId,StepId,TargetUsageId) REFERENCES StepElementUsages(GuideId,StepId,UsageId),FOREIGN KEY(GuideId,VariableId) REFERENCES GuideVariables(GuideId,VariableId));
CREATE TABLE StepExpectedOutcomes(GuideId INTEGER NOT NULL,StepId TEXT NOT NULL,OutcomeKind TEXT NOT NULL,OutcomeDescription TEXT,DefinitionStatus TEXT NOT NULL CHECK(DefinitionStatus IN ('RequiresAuthorConfirmation','AuthorConfirmed')),PRIMARY KEY(GuideId,StepId),FOREIGN KEY(GuideId,StepId) REFERENCES GuideSteps(GuideId,StepId) ON DELETE CASCADE);
CREATE TABLE StepAdvancePolicies(GuideId INTEGER NOT NULL,StepId TEXT NOT NULL,PolicyKind TEXT NOT NULL CHECK(PolicyKind IN ('AutomaticOnValidation','Manual')),SourceKind TEXT NOT NULL,PRIMARY KEY(GuideId,StepId),FOREIGN KEY(GuideId,StepId) REFERENCES GuideSteps(GuideId,StepId) ON DELETE CASCADE);
CREATE TABLE StepObservedSignals(GuideId INTEGER NOT NULL,StepId TEXT NOT NULL,SignalId TEXT NOT NULL,SignalOrder INTEGER NOT NULL,SignalRole TEXT NOT NULL CHECK(SignalRole IN ('PrimaryValidation','AdditionalCompletionCondition')),Kind TEXT NOT NULL,TargetUsageId TEXT,ExpectedValue TEXT,OptionsJson TEXT,DefinitionSource TEXT NOT NULL,PRIMARY KEY(GuideId,StepId,SignalId),UNIQUE(GuideId,StepId,SignalOrder),FOREIGN KEY(GuideId,StepId) REFERENCES GuideSteps(GuideId,StepId) ON DELETE CASCADE,FOREIGN KEY(GuideId,StepId,TargetUsageId) REFERENCES StepElementUsages(GuideId,StepId,UsageId));
CREATE VIEW ReadableStepSemantics AS SELECT g.GuideName,s.GuideId,s.StepId,s.StepOrder,b.Content AS InstructionText,i.InteractionKind AS RequiredInteraction,i.IsAuthorConfirmed AS InteractionConfirmed,o.OutcomeKind AS ExpectedOutcome,o.DefinitionStatus AS OutcomeDefinitionStatus,a.PolicyKind AS AdvancePolicy,(SELECT group_concat(z.SignalRole||': '||z.Kind,'; ') FROM (SELECT SignalRole,Kind FROM StepObservedSignals WHERE GuideId=s.GuideId AND StepId=s.StepId ORDER BY SignalOrder) z) AS ObservedSignals FROM GuideSteps s JOIN Guides g ON g.GuideId=s.GuideId LEFT JOIN StepBubbles b ON b.GuideId=s.GuideId AND b.StepId=s.StepId LEFT JOIN StepInteractions i ON i.GuideId=s.GuideId AND i.StepId=s.StepId LEFT JOIN StepExpectedOutcomes o ON o.GuideId=s.GuideId AND o.StepId=s.StepId LEFT JOIN StepAdvancePolicies a ON a.GuideId=s.GuideId AND a.StepId=s.StepId;
